CREATE TYPE public.farm_account_role AS ENUM ('owner','customer');
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.farm_account_role NOT NULL);
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read own account role" ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
INSERT INTO public.user_roles(user_id,role) SELECT u.id, CASE WHEN EXISTS(SELECT 1 FROM public.animals a WHERE a.user_id=u.id) OR EXISTS(SELECT 1 FROM public.customers c WHERE c.user_id=u.id) OR EXISTS(SELECT 1 FROM public.payments p WHERE p.user_id=u.id) THEN 'owner'::public.farm_account_role WHEN EXISTS(SELECT 1 FROM public.customer_access ca WHERE ca.viewer_id=u.id) OR u.raw_user_meta_data->>'account_type'='customer' THEN 'customer'::public.farm_account_role ELSE 'owner'::public.farm_account_role END FROM auth.users u;
CREATE FUNCTION public.is_farm_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='owner') $$;
REVOKE ALL ON FUNCTION public.is_farm_owner() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.is_farm_owner() TO authenticated;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
INSERT INTO public.profiles(id,full_name) VALUES(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name',split_part(new.email,'@',1)));
INSERT INTO public.user_roles(user_id,role) VALUES(new.id,CASE WHEN new.raw_user_meta_data->>'account_type'='customer' THEN 'customer'::public.farm_account_role ELSE 'owner'::public.farm_account_role END);
RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.owns_animal(_animal_id text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_farm_owner() AND EXISTS(SELECT 1 FROM public.animals WHERE id=_animal_id AND user_id=auth.uid()) $$;
CREATE FUNCTION public.can_read_animal_care(_animal_id text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.owns_animal(_animal_id) OR EXISTS(SELECT 1 FROM public.animals a JOIN public.customer_access ca ON ca.customer_id=a.owner_id AND ca.owner_id=a.user_id JOIN public.user_roles r ON r.user_id=ca.viewer_id AND r.role='customer' WHERE a.id=_animal_id AND ca.viewer_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.can_read_animal_care(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_read_animal_care(text) TO authenticated;
ALTER POLICY "anyone signed in can view animals" ON public.animals USING (user_id=auth.uid() AND public.is_farm_owner());
ALTER POLICY "insert own animals" ON public.animals WITH CHECK (user_id=auth.uid() AND public.is_farm_owner());
ALTER POLICY "update own animals" ON public.animals USING (user_id=auth.uid() AND public.is_farm_owner()) WITH CHECK (user_id=auth.uid() AND public.is_farm_owner());
ALTER POLICY "delete own animals" ON public.animals USING (user_id=auth.uid() AND public.is_farm_owner());
ALTER POLICY "own customers" ON public.customers USING(user_id=auth.uid() AND public.is_farm_owner()) WITH CHECK(user_id=auth.uid() AND public.is_farm_owner());
ALTER POLICY "own payments" ON public.payments USING(user_id=auth.uid() AND public.is_farm_owner()) WITH CHECK(user_id=auth.uid() AND public.is_farm_owner());
ALTER POLICY "insert own categories" ON public.categories WITH CHECK(user_id=auth.uid() AND public.is_farm_owner());
ALTER POLICY "update own categories" ON public.categories USING(user_id=auth.uid() AND public.is_farm_owner()) WITH CHECK(user_id=auth.uid() AND public.is_farm_owner());
ALTER POLICY "delete own categories" ON public.categories USING(user_id=auth.uid() AND public.is_farm_owner());
ALTER POLICY "view weights" ON public.weights USING(public.can_read_animal_care(animal_id));
ALTER POLICY "view vaccinations" ON public.vaccinations USING(public.can_read_animal_care(animal_id));
CREATE OR REPLACE FUNCTION public.connect_customer(_code text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.customer_invites; BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='customer') THEN RAISE EXCEPTION 'Sign in with a customer account to accept this invitation'; END IF;
SELECT * INTO i FROM public.customer_invites WHERE token_hash=encode(sha256(_code::bytea),'hex') AND email=lower(auth.jwt()->>'email') AND expires_at>now() AND used_at IS NULL FOR UPDATE;
IF NOT FOUND THEN RAISE EXCEPTION 'Invalid or expired code for this account'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.customers WHERE id=i.customer_id AND user_id=i.owner_id) THEN RAISE EXCEPTION 'Customer unavailable'; END IF;
INSERT INTO public.customer_access(customer_id,owner_id,viewer_id) VALUES(i.customer_id,i.owner_id,auth.uid()) ON CONFLICT DO NOTHING;
UPDATE public.customer_invites SET used_at=now() WHERE customer_id=i.customer_id; END $$;
CREATE TABLE public.animal_health (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), animal_id text NOT NULL REFERENCES public.animals(id), date date NOT NULL DEFAULT CURRENT_DATE, condition text NOT NULL, details text NOT NULL DEFAULT '', medicine text NOT NULL DEFAULT '', treatment text NOT NULL DEFAULT '', recovery text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Monitoring');
GRANT SELECT,INSERT ON public.animal_health TO authenticated;
GRANT ALL ON public.animal_health TO service_role;
ALTER TABLE public.animal_health ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read permitted health" ON public.animal_health FOR SELECT TO authenticated USING(public.can_read_animal_care(animal_id));
CREATE POLICY "owner appends health history" ON public.animal_health FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.owns_animal(animal_id));
CREATE TABLE public.customer_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), viewer_id uuid NOT NULL, owner_id uuid NOT NULL, customer_id uuid NOT NULL REFERENCES public.customers(id), animal_id text NOT NULL REFERENCES public.animals(id), title text NOT NULL, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz);
GRANT SELECT,UPDATE ON public.customer_notifications TO authenticated;
GRANT ALL ON public.customer_notifications TO service_role;
ALTER TABLE public.customer_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "customer reads assigned notifications" ON public.customer_notifications FOR SELECT TO authenticated USING(viewer_id=auth.uid() AND EXISTS(SELECT 1 FROM public.customer_access ca WHERE ca.customer_id=customer_notifications.customer_id AND ca.owner_id=customer_notifications.owner_id AND ca.viewer_id=auth.uid()) AND public.can_read_animal_care(animal_id));
CREATE POLICY "customer marks own notification" ON public.customer_notifications FOR UPDATE TO authenticated USING(viewer_id=auth.uid() AND public.can_read_animal_care(animal_id)) WITH CHECK(viewer_id=auth.uid() AND public.can_read_animal_care(animal_id));
REVOKE UPDATE ON public.customer_notifications FROM authenticated;
GRANT UPDATE(read_at) ON public.customer_notifications TO authenticated;
CREATE FUNCTION public.notify_animal_update() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.animals; t text; m text; BEGIN
SELECT * INTO a FROM public.animals WHERE id=new.animal_id;
IF a.owner_id IS NULL THEN RETURN new; END IF;
IF TG_TABLE_NAME='animal_health' THEN t:='Health update'; m:=new.condition || ' · ' || new.status;
ELSIF TG_TABLE_NAME='weights' THEN t:='Growth update'; m:=new.kg::text || ' kg recorded';
ELSE t:='Vaccination update'; m:=new.name || ' recorded'; END IF;
INSERT INTO public.customer_notifications(viewer_id,owner_id,customer_id,animal_id,title,message) SELECT ca.viewer_id,a.user_id,a.owner_id,a.id,t,m FROM public.customer_access ca JOIN public.user_roles r ON r.user_id=ca.viewer_id AND r.role='customer' WHERE ca.customer_id=a.owner_id AND ca.owner_id=a.user_id;
RETURN new; END $$;
CREATE TRIGGER health_customer_update AFTER INSERT ON public.animal_health FOR EACH ROW EXECUTE FUNCTION public.notify_animal_update();
CREATE TRIGGER weight_customer_update AFTER INSERT ON public.weights FOR EACH ROW EXECUTE FUNCTION public.notify_animal_update();
CREATE TRIGGER vaccine_customer_update AFTER INSERT ON public.vaccinations FOR EACH ROW EXECUTE FUNCTION public.notify_animal_update();
CREATE FUNCTION public.shared_animal(_animal_id text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
RETURN (SELECT jsonb_build_object('id',a.id,'userId',a.user_id,'categoryId',a.category_id,'subcategoryId',a.subcategory_id,'species',c.name,'sub',coalesce(s.name,''),'breed',a.breed,'ownerId','','status',a.status,'arrival',a.arrival,'monthlyCharge',0,'notes','','photoPath',NULL,'photoUrl',NULL,'vaccineDue',coalesce(a.vaccine_due::text,''),'soldDate',NULL,'soldPrice',NULL,'weights',coalesce((SELECT jsonb_agg(jsonb_build_object('id',w.id,'date',w.date,'kg',w.kg) ORDER BY w.date) FROM public.weights w WHERE w.animal_id=a.id AND w.user_id=a.user_id),'[]'::jsonb),'vaccinations',coalesce((SELECT jsonb_agg(jsonb_build_object('id',v.id,'name',v.name,'date',v.date,'nextDue',v.next_due)) FROM public.vaccinations v WHERE v.animal_id=a.id AND v.user_id=a.user_id),'[]'::jsonb)) FROM public.animals a LEFT JOIN public.categories c ON c.id=a.category_id LEFT JOIN public.categories s ON s.id=a.subcategory_id WHERE upper(a.id)=upper(_animal_id)); END $$;
REVOKE ALL ON FUNCTION public.shared_animal(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.shared_animal(text) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.customer_notifications;
CREATE INDEX animal_health_animal_date ON public.animal_health(animal_id,date);
CREATE INDEX customer_notifications_viewer ON public.customer_notifications(viewer_id,created_at);